examples.code:
#include <stdio.h>

int main(void) {
    int age;
    double height;
    printf("Age and height: ");
    if (scanf("%d %lf", &age, &height) != 2) {
        printf("Invalid input\n");
        return 1;
    }
    printf("age=%d height=%.2f\n", age, height);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char name[16];
    if (fgets(name, sizeof name, stdin) == NULL) return 1;
    name[strcspn(name, "\n")] = '\0';
    printf("[%s] length=%zu\n", name, strlen(name));
    return 0;
}

