lab.solution:
#include <stdio.h>
#include <string.h>

int main(void) {
    char name[64];
    int age;
    double marks;
    fgets(name, sizeof name, stdin);
    name[strcspn(name, "\n")] = '\0';
    if (scanf("%d %lf", &age, &marks) != 2) return 1;
    printf("Name : %s\n", name);
    printf("Age  : %d\n", age);
    printf("Marks: %.2f\n", marks);
    return 0;
}
